/**
 * Auth routes — split out of server.js (2026-07-21). Login validates against
 * the `accounts` table (see data.js). Accounts are managed by users with the
 * "manageAccounts" permission on the Account control page. The seeded first
 * login is staff_194 / password123!.
 *
 * Passwords are bcrypt-hashed (see data.js) and the session token is a
 * signed JWT (see ../auth.js) — set JWT_SECRET in backend/.env for production.
 */
import { Router } from "express";
import multer from "multer";
import { wrap } from "../lib/wrap.js";
import { rateLimit } from "../lib/rateLimit.js";
// signKioskToken is deliberately NOT imported any more — see the note where the
// public kiosk-token endpoint used to be, further down.
import { makeToken, accountFromReq, requireAuth } from "../lib/auth.js";
import { isConfigured as photoStorageConfigured, uploadImage, destroyImage } from "../lib/cloudinary.js";
import {
  getAccountByUsername,
  verifyPassword,
  upgradePasswordIfNeeded,
  startNewSession,
  accountPermissions,
  resetPassword,
  touchLastSeen,
  clearLastSeen,
  registerAccount,
  updateOwnAccount,
  setAccountPhoto,
  clearAccountPhoto,
} from "../data.js";

const router = Router();

// 10 attempts per 10 minutes per IP on the credential endpoints.
const authLimiter = rateLimit({
  windowMs: 10 * 60 * 1000,
  max: 10,
  message: "Too many attempts. Please wait a few minutes and try again.",
});

router.post("/api/auth/login", authLimiter, wrap(async (req, res) => {
  const { staffId, password } = req.body || {};

  if (!staffId || !password) {
    return res.status(400).json({ error: "MISSING_FIELDS", message: "Staff ID and password are required." });
  }

  const acc = await getAccountByUsername(staffId);
  if (!acc || !(await verifyPassword(password, acc.password))) {
    return res.status(401).json({ error: "INVALID_CREDENTIALS", message: "Incorrect Staff ID or password." });
  }
  // Self-registered accounts (2026-07-24) can't log in until an admin
  // approves them on Account control — checked AFTER the password verifies
  // (not before) so a wrong-password guess against a pending account still
  // just looks like "incorrect credentials", not a hint that the account
  // exists and is mid-review.
  if (acc.status === "pending") {
    return res.status(403).json({ error: "ACCOUNT_PENDING", message: "Your account is awaiting admin approval." });
  }
  if (acc.status === "rejected") {
    return res.status(403).json({ error: "ACCOUNT_REJECTED", message: "Your registration was not approved. Contact an admin." });
  }
  await upgradePasswordIfNeeded(acc, password);
  authLimiter.clear(req); // successful login — reset this IP's attempt counter

  // Start a fresh session — invalidates any token held by an older browser.
  const tokenVersion = await startNewSession(acc.id);

  // "id" added (2026-08-03) — the delegate ownership/lock feature needs the
  // signed-in account's OWN id client-side, to compare against a delegate's
  // createdByAccountId and decide whether to show Edit/Delete/Lock as
  // enabled — previously the login/session responses only ever returned
  // role/name/username, never the account's own id.
  res.json({
    token: makeToken(acc.username, tokenVersion),
    id: acc.id,
    role: acc.role,
    readOnly: !!acc.readOnly,
    name: acc.name,
    username: acc.username,
    permissions: accountPermissions(acc),
  });
}));

/**
 * POST /api/auth/register — public self-service sign-up (2026-07-24). Email
 * + username + password, all required (see registerAccount() in
 * db/accounts.js for the exact validation). Always creates a "staff" account
 * in "pending" status — it exists in the DB but CANNOT sign in (see the
 * status check on /api/auth/login above) until an admin approves it on
 * Account control. Rate-limited with the same authLimiter as login/reset —
 * a public, unauthenticated endpoint that writes to the accounts table is
 * exactly the kind of thing worth throttling.
 */
router.post("/api/auth/register", authLimiter, wrap(async (req, res) => {
  const { email, username, password } = req.body || {};
  if (!email || !username || !password) {
    return res.status(400).json({ error: "MISSING_FIELDS", message: "Email, username, and password are all required." });
  }
  const result = await registerAccount({ email, username, password });
  if (result.error) {
    const status = result.error === "USERNAME_TAKEN" || result.error === "EMAIL_TAKEN" ? 409 : 400;
    return res.status(status).json({
      error: result.error,
      message: result.message || "Couldn't create that account. Check your details and try again.",
    });
  }
  authLimiter.clear(req);
  res.status(201).json({ ok: true, message: "Account created — awaiting admin approval before you can sign in." });
}));

// "Forgot password" self-service reset. Public (no token — you don't have a
// valid session, that's the point), username + new password only. See the
// comment on resetPassword() in data.js for why this is intentionally simple
// and not safe as-is for a real public deployment.
router.post("/api/auth/reset-password", authLimiter, wrap(async (req, res) => {
  const { username, newPassword } = req.body || {};
  if (!username || !newPassword) {
    return res.status(400).json({ error: "MISSING_FIELDS", message: "Username and new password are required." });
  }
  const result = await resetPassword(username, newPassword);
  if (result.error) {
    const status = result.error === "WEAK_PASSWORD" ? 400 : 400;
    return res.status(status).json({
      error: result.error,
      message: result.message || "Couldn't reset that account. Check the username and try again.",
    });
  }
  res.json({ ok: true });
}));

/**
 * GET /api/auth/session — returns the CURRENT permissions/details for the
 * signed-in account, straight from the database (never cached). The frontend
 * polls this so that if someone with "manageAccounts" changes YOUR account
 * (permissions, username, or deletes it) while you're logged in elsewhere, you
 * get logged out automatically instead of carrying on with stale access shown
 * in the UI. Returns 401 if the account was renamed or deleted (the old token
 * no longer resolves to anyone).
 */
router.get("/api/auth/session", wrap(async (req, res) => {
  const acc = await accountFromReq(req);
  if (!acc) return res.status(401).json({ error: "UNAUTHENTICATED", message: "Your session is no longer valid." });
  await touchLastSeen(acc.id); // powers the Staff Operations "active now" list
  res.json({
    id: acc.id,
    username: acc.username,
    name: acc.name,
    email: acc.email || null,
    photoUrl: acc.photoUrl || null,
    role: acc.role,
    readOnly: !!acc.readOnly,
    permissions: accountPermissions(acc),
  });
}));

/**
 * POST /api/auth/logout — clears this account's last_seen_at immediately, so
 * the Staff Operations "active now" list reflects an explicit logout right
 * away instead of showing the account as still active until the 45s window
 * lapses. Best-effort from the frontend's side (the client clears its own
 * token regardless of whether this call succeeds).
 */
router.post("/api/auth/logout", requireAuth(), wrap(async (req, res) => {
  const acc = await accountFromReq(req);
  if (acc) await clearLastSeen(acc.id);
  res.json({ ok: true });
}));

/**
 * PATCH /api/auth/me — self-service "edit my profile" (2026-07-24, Settings
 * page). ANY signed-in account can call this on their OWN id — no
 * manageAccounts permission needed, unlike the admin-only PATCH
 * /api/accounts/:id. Can change name/username/email/password; can NEVER
 * touch role or permissions (see updateOwnAccount() in db/accounts.js,
 * which doesn't even accept those fields). Changing the password requires
 * `currentPassword` to verify identity first.
 *
 * Always hands back a fresh token — editing your own username invalidates
 * the OLD token's embedded username lookup, so the frontend must swap to
 * this new one immediately rather than getting silently logged out.
 */
router.patch("/api/auth/me", requireAuth(), wrap(async (req, res) => {
  const result = await updateOwnAccount(req.account.id, req.body || {});
  if (result.error) {
    const status = result.error === "USERNAME_TAKEN" || result.error === "EMAIL_TAKEN" ? 409
      : result.error === "CURRENT_PASSWORD_INCORRECT" ? 401
      : 400;
    const message = result.message
      || (result.error === "CURRENT_PASSWORD_INCORRECT" ? "Your current password is incorrect." : undefined)
      || "Couldn't save your profile. Check your details and try again.";
    return res.status(status).json({ error: result.error, message });
  }
  res.json({
    account: result.account,
    token: makeToken(result.account.username, req.account.token_version ?? 0),
  });
}));

// Profile photo uploads — memory storage (never touches local disk), same
// 5MB/image-only guard as the delegate photo route in routes/dashboard/delegates.js.
const profilePhotoUpload = multer({
  storage: multer.memoryStorage(),
  limits: { fileSize: 5 * 1024 * 1024 },
  fileFilter: (_req, file, cb) => {
    if (!file.mimetype.startsWith("image/")) return cb(new Error("UNSUPPORTED_TYPE"));
    cb(null, true);
  },
});

router.post("/api/auth/me/photo", requireAuth(), (req, res, next) => {
  profilePhotoUpload.single("photo")(req, res, (err) => {
    if (err) {
      const code = err.message === "UNSUPPORTED_TYPE" ? "UNSUPPORTED_TYPE" : "UPLOAD_FAILED";
      const message = code === "UNSUPPORTED_TYPE" ? "Please upload an image file." : "Upload too large (5MB max) or failed.";
      return res.status(400).json({ error: code, message });
    }
    next();
  });
}, wrap(async (req, res) => {
  if (!photoStorageConfigured()) {
    return res.status(503).json({ error: "PHOTO_STORAGE_NOT_CONFIGURED", message: "Photo storage isn't set up on this server yet." });
  }
  if (!req.file) return res.status(400).json({ error: "FILE_REQUIRED", message: "Please choose an image." });

  // A SEPARATE Cloudinary folder from delegate photos (see the schema.js
  // comment on this column) — never touched by the delegates-only media
  // manager's "purge all" action.
  const { url, publicId } = await uploadImage(req.file.buffer, "mustergo/accounts");
  const oldPublicId = await setAccountPhoto(req.account.id, url, publicId);
  if (oldPublicId) await destroyImage(oldPublicId); // replacing a photo — clean up the old asset

  res.json({ photoUrl: url });
}));

router.delete("/api/auth/me/photo", requireAuth(), wrap(async (req, res) => {
  const oldPublicId = await clearAccountPhoto(req.account.id);
  if (oldPublicId) await destroyImage(oldPublicId);
  res.json({ deleted: true });
}));

/**
 * REMOVED 2026-08-05: POST /api/auth/kiosk used to mint a passwordless kiosk
 * token to ANY caller — no credentials, no rate limit, 8h validity.
 *
 * The original note said it was safe because the token "only" reached the two
 * camera check-in endpoints. That reasoning didn't hold: one of those,
 * POST /api/checkpoints/:id/checkins, takes a RAW `{ delegateId, status }`
 * body — no scanned badge required — and delegate ids are sequential (`d-1`,
 * `d-2`, … see nextId() in db/delegates.js). So anyone who could reach the
 * server could mint a token and mark any delegate ARRIVED/MISSING/LATE at any
 * checkpoint, with no admin involvement. For an attendance system whose whole
 * value is a trustworthy headcount, that's an integrity hole, not a shortcut.
 *
 * The scanner now runs on a NORMAL staff session (KioskScannerPage.jsx), so it
 * is scoped to that account's own trip/coach and every check-in is attributable.
 * Convenience is preserved by the existing passkey flow below — face/fingerprint
 * sign-in after the first password login.
 *
 * signKioskToken()/requireKioskOrAuth()/requireKioskOrPermission() are left in
 * lib/auth.js on purpose: the two require* helpers still authorise ordinary
 * signed-in accounts by permission, which is how those routes work now. Nothing
 * can issue a kiosk token any more. Do NOT re-add this endpoint without a
 * server-side pairing step (an admin-generated, short-lived code) — see AI Log 261.
 */

export default router;
